package com.sunwayworld.framework;
import com.sunwayworld.owned.internal.web.OwnedIdentityConfiguration;
import com.sunwayworld.owned.internal.web.OwnedSampleSetQueryController;
import java.lang.reflect.Method;import java.util.Arrays;import java.util.HashSet;import java.util.Set;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PostMapping;
public final class OwnedSampleSetQueryControllerContractTest{public static void main(String[] args){Set<String> paths=new HashSet<String>();for(Method method:OwnedSampleSetQueryController.class.getDeclaredMethods()){PostMapping post=method.getAnnotation(PostMapping.class);if(post!=null)paths.addAll(Arrays.asList(post.path()));GetMapping get=method.getAnnotation(GetMapping.class);if(get!=null)paths.addAll(Arrays.asList(get.path()));}for(String path:new String[]{"/secure/emc/module/bp/sample-sets/queries","/secure/emc/module/bp/sample-sets/queries/raw","/secure/emc/module/bp/sample-sets/queries/searchable","/secure/emc/module/bp/sample-sets/info/status","/secure/emc/module/bp/sample-sets/{id}"})if(!paths.contains(path))throw new AssertionError("missing sample-set route "+path);boolean registered=false;for(Method method:OwnedIdentityConfiguration.class.getDeclaredMethods())if(method.getReturnType()==OwnedSampleSetQueryController.class)registered=true;if(!registered)throw new AssertionError("sample-set controller is not registered");System.out.println("owned sample-set query contract checks passed");}}
